const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const f = line.split(/\s+/)
    const fail = (r) => { throw new Fail(`error: line ${i + 1}: ${r}`) }
    const num = (v, field, least) => {
      if (!INT.test(v) || BigInt(v) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const d = f[0]
    if (!['bucket', 'window', 'route', 'event'].includes(d)) fail(`unknown directive ${d}`)
    if (d !== 'event' && events.length) fail('declarations must come before the first event')
    if (d === 'bucket') {
      if (f.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
      if (!NAME.test(f[1])) fail(`invalid policy name ${f[1]}`)
      const capacity = num(f[2], 'capacity', 1)
      const refill = num(f[3], 'refill', 0)
      const per = num(f[4], 'per', 1)
      if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
      policies.set(f[1], { name: f[1], kind: 'bucket', capacity, refill, per })
    } else if (d === 'window') {
      if (f.length !== 4) fail('expected window <name> <limit> <span>')
      if (!NAME.test(f[1])) fail(`invalid policy name ${f[1]}`)
      const limit = num(f[2], 'limit', 0)
      const span = num(f[3], 'span', 1)
      if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
      policies.set(f[1], { name: f[1], kind: 'window', limit, span })
    } else if (d === 'route') {
      if (f.length < 3) fail('expected route <prefix> <policy>...')
      if (!NAME.test(f[1])) fail(`invalid route prefix ${f[1]}`)
      if (routes.has(f[1])) fail(`prefix ${f[1]} is routed twice`)
      for (const p of f.slice(2)) if (!policies.has(p)) fail(`unknown policy ${p}`)
      routes.set(f[1], f.slice(2).map((p) => policies.get(p)))
    } else {
      if (f.length !== 3) fail('expected event <tick> <key>')
      const tick = num(f[1], 'tick', 0)
      if (!NAME.test(f[2])) fail(`invalid key ${f[2]}`)
      if (lastTick !== null && tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      events.push({ tick, key: f[2] })
    }
  })
  return { routes, events }
}

let text = ''
process.stdin.setEncoding('utf8')
process.stdin.on('data', (c) => { text += c })
process.stdin.on('end', () => {
  let parsed
  try {
    parsed = parse(text)
  } catch (e) {
    if (!(e instanceof Fail)) throw e
    process.stderr.write(e.message + '\n')
    process.exit(2)
  }
  const { routes, events } = parsed
  const states = new Map() // policy -> Map(key -> state)
  const stateOf = (p, key, tick) => {
    let m = states.get(p)
    if (!m) states.set(p, (m = new Map()))
    let s = m.get(key)
    if (!s) {
      s = p.kind === 'bucket' ? { units: p.capacity * p.per, last: tick } : { ticks: [] }
      m.set(key, s)
    }
    return s
  }
  const out = []
  const per = new Map()
  let ta = 0, td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const pre of routes.keys()) if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    let denier = null
    if (best !== null) {
      const ps = routes.get(best)
      const sts = ps.map((p) => {
        const s = stateOf(p, key, tick)
        if (p.kind === 'bucket') {
          const cap = p.capacity * p.per
          s.units += p.refill * (tick - s.last)
          if (s.units > cap) s.units = cap
          s.last = tick
        } else {
          const cut = tick - p.span
          s.ticks = s.ticks.filter((t) => t > cut)
        }
        return s
      })
      for (let i = 0; i < ps.length && !denier; i++) {
        const p = ps[i]
        const ok = p.kind === 'bucket' ? sts[i].units >= p.per : BigInt(sts[i].ticks.length) < p.limit
        if (!ok) denier = p.name
      }
      if (!denier) {
        ps.forEach((p, i) => {
          if (p.kind === 'bucket') sts[i].units -= p.per
          else sts[i].ticks.push(tick)
        })
      }
    }
    const c = per.get(key) || { a: 0, d: 0 }
    per.set(key, c)
    if (denier) { c.d++; td++ } else { c.a++; ta++ }
    out.push(denier ? `${tick} ${key} deny ${denier}` : `${tick} ${key} allow`)
  }
  if (mode === 'summary') {
    out.length = 0
    for (const k of [...per.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
      out.push(`${k} allowed=${per.get(k).a} denied=${per.get(k).d}`)
    }
    out.push(`total allowed=${ta} denied=${td}`)
  }
  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
})
